ALTER TABLE public.trip_distributions ADD COLUMN pickup_geography_evidence jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE FUNCTION public.pilot_local_instant(_date date,_time time,_zone text) RETURNS timestamptz LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE base timestamptz;n integer;BEGIN IF _zone IS NULL OR _zone NOT IN ('America/New_York','America/Chicago') OR _date IS NULL OR _time IS NULL THEN RETURN NULL;END IF;base:=(_date+_time) AT TIME ZONE _zone;SELECT count(*) INTO n FROM generate_series(base-interval '3 hours',base+interval '3 hours',interval '30 minutes') x WHERE x AT TIME ZONE _zone=_date+_time;IF n<>1 THEN RETURN NULL;END IF;RETURN base;END $$;
CREATE FUNCTION public.pilot_provider_hours(_distribution uuid,_settings jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.trip_distributions;instant timestamptz;local timestamp;z text;BEGIN SELECT * INTO d FROM public.trip_distributions WHERE id=_distribution;z:=_settings->>'timezone';instant:=public.pilot_local_instant(d.pickup_date,d.pickup_time,d.pickup_timezone);IF instant IS NULL OR z IS NULL OR z NOT IN ('America/New_York','America/Chicago') THEN RETURN false;END IF;local:=instant AT TIME ZONE z;IF public.pilot_local_instant(local::date,local::time,z) IS NULL THEN RETURN false;END IF;RETURN coalesce(_settings->'days','[]') @> to_jsonb(ARRAY[extract(dow FROM local)::integer]) AND local::time>=(_settings->>'start')::time AND local::time<(_settings->>'end')::time;EXCEPTION WHEN OTHERS THEN RETURN false;END $$;
CREATE FUNCTION public.pilot_geography_match(_distribution uuid,_counties text[],_region text) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE e jsonb;BEGIN SELECT pickup_geography_evidence INTO e FROM public.trip_distributions WHERE id=_distribution;IF e->>'state' IS DISTINCT FROM 'FL' OR e->>'verified' IS DISTINCT FROM 'true' THEN RETURN '';END IF;IF e->>'county'=ANY(_counties) THEN RETURN 'County service-area match';END IF;IF e->>'region'=_region AND _region IN ('panhandle','northeast','north-central','central','tampa-bay','southwest','southeast') THEN RETURN 'Region service-area match';END IF;RETURN '';END $$;
DO $change$ DECLARE f text;BEGIN SELECT pg_get_functiondef('public.network_acceptance_candidates(uuid,integer,uuid)'::regprocedure) INTO f;
f:=replace(f,'IF d.pickup_timezone IS NULL OR p.matching_settings->>''timezone'' IS DISTINCT FROM d.pickup_timezone THEN reasons:=array_append(reasons,''Explicit same-timezone evidence required'');END IF;', 'IF public.pilot_local_instant(d.pickup_date,d.pickup_time,d.pickup_timezone) IS NULL THEN reasons:=array_append(reasons,''Pickup timezone missing or ambiguous'');END IF;IF p.matching_settings->>''timezone'' IS DISTINCT FROM d.pickup_timezone AND EXISTS(SELECT 1 FROM public.trips t WHERE (t.network_provider_workspace_id=p.id OR EXISTS(SELECT 1 FROM public.drivers v WHERE v.id=t.driver_id AND v.workspace_id=p.id) OR EXISTS(SELECT 1 FROM public.vehicles v WHERE v.id=t.vehicle_id AND v.workspace_id=p.id)) AND t.status NOT IN (''completed'',''canceled'',''cancelled'')) THEN reasons:=array_append(reasons,''Cross-timezone assignment evidence requires review'');END IF;');
f:=replace(f,'IF NOT area OR (distance IS NOT NULL AND distance>_radius) THEN', 'area:=area OR public.pilot_geography_match(d.id,p.counties,p.matching_settings->>''region'')<>''''; IF NOT area OR (distance IS NOT NULL AND distance>_radius AND public.pilot_geography_match(d.id,p.counties,p.matching_settings->>''region'')='''') THEN');
f:=replace(f,'IF coalesce(p.matching_settings->>''timezone'','''') NOT IN (SELECT name FROM pg_timezone_names) OR NOT coalesce(p.matching_settings->''days'',''[]'') @> to_jsonb(ARRAY[extract(dow FROM d.pickup_date)::integer]) OR NOT (d.pickup_time>=coalesce(p.matching_settings->>''start'',''00:00'')::time AND d.pickup_time<coalesce(p.matching_settings->>''end'',''00:00'')::time) THEN','IF NOT public.pilot_provider_hours(d.id,p.matching_settings) THEN');
f:=replace(f,'jsonb_build_array(''Service area match'',''Eligible vehicle and driver'',''Operating during requested time'')','jsonb_build_array(CASE WHEN pickup_zip=ANY(p.zips) THEN ''ZIP service-area match'' WHEN lower(d.pickup_area)=ANY(SELECT lower(x) FROM unnest(p.cities) x) THEN ''City service-area match'' WHEN public.pilot_geography_match(d.id,p.counties,p.matching_settings->>''region'')<>'''' THEN public.pilot_geography_match(d.id,p.counties,p.matching_settings->>''region'') ELSE ''Approved approximate distance match'' END,''Eligible vehicle and driver'',''Operating during requested time'')');EXECUTE f;
SELECT pg_get_functiondef('public.pilot_scope_reason(uuid,uuid)'::regprocedure) INTO f;f:=replace(f,'(d.pickup_date+d.pickup_time) AT TIME ZONE d.pickup_timezone<=now()','(public.pilot_local_instant(d.pickup_date,d.pickup_time,d.pickup_timezone) IS NULL OR public.pilot_local_instant(d.pickup_date,d.pickup_time,d.pickup_timezone)<=now())');EXECUTE f;END $change$;
REVOKE ALL ON FUNCTION public.pilot_local_instant(date,time,text),public.pilot_provider_hours(uuid,jsonb),public.pilot_geography_match(uuid,text[],text) FROM PUBLIC,anon,authenticated;